create table if not exists public.locations (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,code text not null,name text not null,location_type text not null default 'site' check(location_type in ('warehouse','kitchen','cafe','store','site','other')),timezone text,active boolean not null default true,created_at timestamptz not null default now(),unique(business_id,code),unique(business_id,id));
insert into public.locations(business_id,code,name,location_type) select b.id,'MAIN','Main Inventory','site' from public.businesses b where not exists(select 1 from public.locations l where l.business_id=b.id);
alter table public.inventory_movements add column if not exists location_id uuid references public.locations(id);
update public.inventory_movements im set location_id=l.id from public.locations l where l.business_id=im.business_id and l.code='MAIN' and im.location_id is null;
create table if not exists public.inventory_service_targets (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,location_id uuid not null references public.locations(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id) on delete cascade,target_service_level numeric(8,5) not null default .95,target_days_cover numeric(12,4) not null default 0,review_period_days numeric(12,4) not null default 1,unique(business_id,location_id,ingredient_id));
create table if not exists public.ingredient_batches (id uuid primary key default gen_random_uuid(),batch_id uuid not null default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id) on delete restrict,location_id uuid not null references public.locations(id) on delete restrict,batch_code text not null,received_at timestamptz not null default now(),expiry_date date,remaining_quantity numeric(24,8) not null default 0 check(remaining_quantity>=0),unit text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,batch_code,ingredient_id,location_id));
create table if not exists public.stock_transfer_recommendations (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id) on delete cascade,source_location_id uuid not null references public.locations(id),destination_location_id uuid not null references public.locations(id),recommended_quantity numeric(24,8) not null check(recommended_quantity>0),unit text not null,score numeric(24,8) not null default 0,created_at timestamptz not null default now());
create table if not exists public.stock_transfers (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,source_location_id uuid not null references public.locations(id),destination_location_id uuid not null references public.locations(id),status text not null default 'draft' check(status in ('draft','approved','in_transit','received','cancelled')),created_at timestamptz not null default now(),check(source_location_id<>destination_location_id));
create table if not exists public.stock_transfer_lines (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,stock_transfer_id uuid not null references public.stock_transfers(id) on delete cascade,ingredient_id uuid not null references public.ingredients(id),quantity numeric(24,8) not null check(quantity>0),unit text not null,created_at timestamptz not null default now());
alter table public.locations enable row level security; alter table public.inventory_service_targets enable row level security; alter table public.ingredient_batches enable row level security; alter table public.stock_transfer_recommendations enable row level security; alter table public.stock_transfers enable row level security; alter table public.stock_transfer_lines enable row level security;
drop policy if exists v19_locations_select on public.locations; create policy v19_locations_select on public.locations for select using(is_member(business_id));
drop policy if exists v19_targets_select on public.inventory_service_targets; create policy v19_targets_select on public.inventory_service_targets for select using(is_member(business_id));
drop policy if exists v19_batches_select on public.ingredient_batches; create policy v19_batches_select on public.ingredient_batches for select using(is_member(business_id));
drop policy if exists v19_transfer_select on public.stock_transfers; create policy v19_transfer_select on public.stock_transfers for select using(is_member(business_id));
drop policy if exists v19_transfer_lines_select on public.stock_transfer_lines; create policy v19_transfer_lines_select on public.stock_transfer_lines for select using(is_member(business_id));
create or replace view public.v19_location_service_targets with(security_invoker=true) as select l.business_id,l.id location_id,i.id ingredient_id,i.base_unit unit,coalesce(t.target_service_level,.95000)::numeric(8,5) target_service_level,coalesce(t.target_days_cover,0)::numeric(12,4) target_days_cover,coalesce(t.review_period_days,1)::numeric(12,4) review_period_days,(t.id is null) cold_start from public.locations l join public.ingredients i on i.business_id=l.business_id and l.active left join public.inventory_service_targets t on t.business_id=l.business_id and t.location_id=l.id and t.ingredient_id=i.id;
create or replace view public.v19_location_stock with(security_invoker=true) as select im.business_id,im.location_id,im.ingredient_id,i.base_unit unit,coalesce(sum(im.quantity) filter(where im.unit=i.base_unit),0)::numeric(24,8) current_stock,count(*) filter(where im.unit<>i.base_unit)::integer unit_mismatch_count from public.inventory_movements im join public.ingredients i on i.id=im.ingredient_id and i.business_id=im.business_id group by im.business_id,im.location_id,im.ingredient_id,i.base_unit;